import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    expected_width = 4
    header_index = None

    for index, row in enumerate(records):
        if len(row) >= expected_width and any(value.strip() for value in row):
            header_index = index
            break

    if header_index is None:
        for index, row in enumerate(records):
            if any(value.strip() for value in row):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        row = list(record)

        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]

        rows.append(row)

    return {"columns": columns, "rows": rows}
